class t{componentName;isActive=!1;constructor(t){this.componentName=t,this.cssUrl=`/pages/${t}/${t}.css`,this.htmlUrl=`/pages/${t}/${t}.html`}async activate(){if(this.isActive)return this;try{return await this.loadCSS(),await this.loadHTML(),this.isActive=!0,this}catch(t){throw this.showErrorState(t),t}}destroy(){this.isActive&&(this.removeCSS(),this.clearHTML(),this.isActive=!1)}async loadCSS(){if(!document.querySelector(`link[href*="${this.componentName}.css"]`))try{const t=document.createElement("link");return t.rel="stylesheet",t.href=this.cssUrl,new Promise((e,r)=>{t.onload=()=>e(),t.onerror=()=>{e()},document.head.appendChild(t),setTimeout(()=>e(),3e3)})}catch(t){}}async loadHTML(){try{const t=await this.loadComponentHtml(),e=document.getElementById("router-outlet");if(!e)throw new Error("Router outlet not found in DOM");e.innerHTML=t}catch(t){throw t}}clearHTML(){const t=document.getElementById("router-outlet");t&&(t.innerHTML="")}removeCSS(){let t=document.getElementsByTagName("LINK");for(let e=0;e<t.length;e++)t[e].href.includes(this.cssUrl)&&t[e].parentNode.removeChild(t[e])}template(){}async loadComponentHtml(){try{const t=new URL(this.htmlUrl,window.location.origin).href,e=await fetch(t);if(!e.ok)throw new Error(`HTTP ${e.status}: ${t}`);return await e.text()}catch(t){throw t}}showErrorState(t){const e=document.getElementById("router-outlet");e&&(e.innerHTML=`\n        <div class="error-state" role="alert" aria-live="assertive">\n          <h2>Error Loading Page</h2>\n          <p>Sorry, there was an error loading the "${this.componentName}" page.</p>\n          <details>\n            <summary>Technical Details</summary>\n            <pre>${t.message}</pre>\n          </details>\n          <p>\n            <a href="/" class="error-home-link">← Return to Home</a>\n            <button onclick="location.reload()" class="error-retry-button">Try Again</button>\n          </p>\n        </div>\n      `)}}export{t as B};
